"use client";

import Link from "next/link";
import { ArrowRight, Shield, type LucideIcon } from "lucide-react";
import { Container } from "@/components/ui/container";
import { Wrapper } from "@/components/ui/wrapper";
import { SectionBadge } from "@/components/ui/section-badge";
import { Button } from "@/components/ui/button";
import { FadeIn } from "@/components/ui/fade-in";
import { MagicCard } from "@/components/ui/magic-card";
import { Breadcrumb } from "@/components/ui/breadcrumb";
import { useBookingUrl } from "@/lib/use-booking-url";
import { trackLeadEvent } from "@/hooks/use-cookie-consent";
import { servicesData, type ServiceItem } from "@/lib/services-data";
import { toSlug } from "@/lib/utils";

type ServiceSubcategory = ServiceItem["subcategory"];

const CATEGORY_ORDER: ServiceSubcategory[] = [
  "Operations",
  "Growth",
  "Engineering",
  "Infrastructure",
  "Data & Insights",
  "Strategy",
];

const CATEGORY_INTROS: Record<ServiceSubcategory, string> = {
  "Operations":
    "Workflow automations for enquiries, support, follow-ups, and the handoffs your team handles every week.",
  "Growth":
    "Marketing and SEO automations that keep your pipelines, listings, and outreach moving.",
  "Engineering":
    "Custom AI systems and software engineering tailored to your specific workflows.",
  "Infrastructure":
    "Modernised cloud, DevOps, security, and legacy system foundations.",
  "Data & Insights":
    "Reporting, forecasting, and unified data views for clearer operational decisions.",
  "Strategy":
    "Planning, audits, and advisory work that helps teams choose the right automation path before building.",
};

export function ServicesPageClient() {
  const bookingUrl = useBookingUrl();
  const serviceCategories = Array.from(new Set(servicesData.map((service) => service.subcategory)));
  const orderedCategories = [
    ...CATEGORY_ORDER.filter((category) => serviceCategories.includes(category)),
    ...serviceCategories.filter((category) => !CATEGORY_ORDER.includes(category)),
  ];

  const grouped = orderedCategories.map((category) => ({
    category,
    services: servicesData.filter((s) => s.subcategory === category),
  }));

  return (
    <div className="flex flex-col w-full min-h-screen relative bg-background">
      {/* Hero */}
      <Wrapper className="py-12 md:py-24">
        <Container>
          <div className="mb-5 md:mb-8">
            <Breadcrumb items={[{ label: "Services" }]} />
          </div>

          <FadeIn className="max-w-3xl mx-auto text-center">
            <SectionBadge title="Services" className="mb-4 md:mb-6" />
            <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold mb-4 md:mb-6 leading-tight tracking-tight">
              AI Workflow Automation Services
            </h1>
            <p className="text-base md:text-xl text-muted-foreground leading-relaxed">
              Arbor studies how work moves across your team, then uses AI, automation, integrations, or custom software where they make sense. Every system is built around your existing tools, with human review where decisions matter.
            </p>
          </FadeIn>

          <FadeIn delay={0.1}>
            <div className="flex flex-wrap items-center justify-center gap-x-6 gap-y-2 text-sm text-muted-foreground mt-5 md:mt-6">
              <span className="inline-flex items-center gap-2">
                <Shield className="w-4 h-4 text-primary" />
                Review before key actions
              </span>
              <span className="inline-flex items-center gap-2">
                <Shield className="w-4 h-4 text-primary" />
                Limited tool permissions
              </span>
              <span className="inline-flex items-center gap-2">
                <Shield className="w-4 h-4 text-primary" />
                Logs and handover docs
              </span>
            </div>
          </FadeIn>
        </Container>
      </Wrapper>

      {/* Compact category overview */}
      <Wrapper className="py-6 md:py-10 border-y border-border/50 bg-muted/20">
        <Container>
          <FadeIn>
            <div className="flex flex-wrap items-center justify-center gap-x-6 gap-y-3 text-sm">
              <span className="text-muted-foreground font-medium">Browse by area:</span>
              {grouped.map(({ category }) => (
                <a
                  key={category}
                  href={`#category-${toSlug(category)}`}
                  className="text-foreground hover:text-primary transition-colors font-medium"
                >
                  {category}
                </a>
              ))}
            </div>
          </FadeIn>
        </Container>
      </Wrapper>

      {/* Service cards grouped by category */}
      {grouped.map(({ category, services }, sectionIdx) => (
        <Wrapper
          key={category}
          id={`category-${toSlug(category)}`}
          className={`py-10 md:py-20 ${sectionIdx === 0 ? "border-t border-border/50" : ""} ${
            sectionIdx % 2 === 1 ? "bg-muted/20" : ""
          }`}
        >
          <Container>
            <FadeIn className="max-w-3xl mx-auto text-center mb-10 md:mb-14">
              <SectionBadge title={category} className="mb-4 md:mb-6" />
              <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold mb-4 md:mb-5 leading-tight">
                {category} Workflow Automation
              </h2>
              <p className="text-base md:text-lg text-muted-foreground">
                {CATEGORY_INTROS[category]}
              </p>
            </FadeIn>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6 max-w-6xl mx-auto">
              {services.map((service, i) => {
                const Icon: LucideIcon = service.icon;
                return (
                  <FadeIn key={service.title} delay={i * 0.05}>
                    <MagicCard className="p-5 md:p-6 h-full flex flex-col">
                      <div className="mb-4 w-10 h-10 md:w-11 md:h-11 rounded-md bg-primary/10 flex items-center justify-center">
                        <Icon className="w-5 h-5 text-primary" />
                      </div>
                      <h3 className="text-base md:text-lg font-semibold mb-2 text-foreground">
                        {service.title}
                      </h3>
                      <p className="text-sm text-muted-foreground leading-relaxed flex-1">
                        {service.description}
                      </p>
                      <div className="mt-5 pt-4 border-t border-border/50">
                        <Link
                          href={`/services/${toSlug(service.title)}`}
                          className="inline-flex items-center gap-1 text-sm font-semibold text-foreground hover:text-primary transition-colors"
                          aria-label={`View full page for ${service.title}`}
                          data-gtm-service-list={service.title}
                        >
                          View service
                          <ArrowRight className="w-3.5 h-3.5" />
                        </Link>
                      </div>
                    </MagicCard>
                  </FadeIn>
                );
              })}
            </div>
          </Container>
        </Wrapper>
      ))}

      {/* Final CTA */}
      <Wrapper className="py-20 md:py-24 border-t border-border/50 bg-muted/30">
        <Container>
          <FadeIn className="max-w-3xl mx-auto text-center">
            <SectionBadge title="Workflow Fit Call" className="mb-6" />
            <h2 className="text-3xl md:text-4xl lg:text-5xl font-bold mb-5 leading-tight">
              Start With One Workflow Your Team Repeats
            </h2>
            <p className="text-base md:text-lg text-muted-foreground mb-8">
              Choose a workflow your team handles every week. We map the steps, add review points, and connect the tools already in use.
            </p>
            <div className="flex flex-col sm:flex-row gap-4 items-center justify-center">
              <Button
                size="lg"
                asChild
                className="gap-2 shadow-sm w-full sm:w-auto"
                id="btn-book-meeting-services-cta"
              >
                <a
                  href={bookingUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={() => trackLeadEvent({ source: 'services_cta_button' })}
                >
                  Book a Workflow Fit Call
                  <ArrowRight className="w-4 h-4" />
                </a>
              </Button>
              <Button
                size="lg"
                variant="outline"
                asChild
                className="gap-2 w-full sm:w-auto"
                id="btn-start-one-workflow"
              >
                <Link href="/#solutions">
                  Start with one workflow
                </Link>
              </Button>
            </div>
          </FadeIn>
        </Container>
      </Wrapper>
    </div>
  );
}
