import React from "react";
import { cn } from "@/lib/utils";

export interface MagicCardProps extends React.HTMLAttributes<HTMLDivElement> {
  gradientSize?: number;
  gradientColor?: string;
  gradientOpacity?: number;
}

export function MagicCard({
  children,
  className,
  gradientSize = 140,
  gradientColor = "#86a447",
  gradientOpacity = 0.08,
  ...props
}: MagicCardProps) {
  return (
    <div
      {...props}
      className={cn(
        "group relative flex size-full overflow-hidden rounded-xl border border-border/80 bg-card text-foreground shadow-sm dark:shadow-none",
        className,
      )}
    >
      <div className="relative z-10 w-full">{children}</div>
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -inset-px rounded-xl transition-opacity duration-300"
        style={{
          background: `radial-gradient(${gradientSize}px circle at 50% 0%, ${gradientColor}, transparent 80%)`,
          opacity: gradientOpacity,
        }}
      />
    </div>
  );
}
